#include <WiFi.h>
#include <WebServer.h>
#include <Update.h>
#include <Preferences.h>
#include <esp_netif.h>

Preferences prefs;
WebServer server(80);

const char* AP_SSID = "VALLIAN-REPEATER";
const char* AP_PASS = "12345678";

String ssid;
String pass;
bool natOK = false;

void connectWiFi() {
  if (!ssid.length()) return;

  WiFi.begin(ssid.c_str(), pass.c_str());

  Serial.print("Connecting");

  for (int i = 0; i < 30; i++) {
    if (WiFi.status() == WL_CONNECTED) break;

    delay(500);
    Serial.print(".");
  }

  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    Serial.print("Connected: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("Connection failed");
  }
}

void enableNAT() {
  esp_netif_t* ap =
    esp_netif_get_handle_from_ifkey("WIFI_AP_DEF");

  if (!ap) {
    Serial.println("AP interface not found");
    return;
  }

  esp_err_t err =
    esp_netif_napt_enable(ap);

  natOK = err == ESP_OK;

  Serial.print("NAT: ");
  Serial.println(
    natOK
      ? "ACTIVE"
      : esp_err_to_name(err)
  );
}

String page() {
  String h =
    "<html><meta name='viewport' "
    "content='width=device-width,initial-scale=1'>"
    "<body style='background:#090908;color:white;"
    "font-family:Arial;padding:24px'>"
    "<h2 style='color:#f2c94c'>VALLIAN REPEATER</h2>";

  if (WiFi.status() == WL_CONNECTED) {
    h += "WiFi: " + WiFi.SSID();
    h += "<br>RSSI: ";
    h += String(WiFi.RSSI());
    h += " dBm<br>";
  } else {
    h += "WiFi: NOT CONNECTED<br>";
  }

  h += natOK
    ? "NAT: ACTIVE"
    : "NAT: NOT ACTIVE";

  h +=
    "<hr>"
    "<form method='POST' action='/save'>"
    "<input name='ssid' placeholder='WiFi SSID'><br><br>"
    "<input name='pass' type='password' placeholder='Password'><br><br>"
    "<button>CONNECT</button>"
    "</form>"
    "<hr>"
    "<form method='POST' action='/update' "
    "enctype='multipart/form-data'>"
    "<input type='file' name='firmware'>"
    "<button>UPLOAD BIN</button>"
    "</form>"
    "</body></html>";

  return h;
}

void setupWeb() {
  server.on("/", HTTP_GET, []() {
    server.send(
      200,
      "text/html",
      page()
    );
  });

  server.on("/save", HTTP_POST, []() {
    ssid = server.arg("ssid");
    pass = server.arg("pass");

    prefs.putString("ssid", ssid);
    prefs.putString("pass", pass);

    server.send(
      200,
      "text/plain",
      "Saved. Restarting..."
    );

    delay(1000);
    ESP.restart();
  });

  server.on(
    "/update",
    HTTP_POST,

    []() {
      bool ok = !Update.hasError();

      server.send(
        ok ? 200 : 500,
        "text/plain",
        ok ? "OTA SUCCESS" : "OTA FAILED"
      );

      if (ok) {
        delay(800);
        ESP.restart();
      }
    },

    []() {
      HTTPUpload& u = server.upload();

      if (u.status == UPLOAD_FILE_START) {
        Update.begin(UPDATE_SIZE_UNKNOWN);
      }

      else if (u.status == UPLOAD_FILE_WRITE) {
        Update.write(
          u.buf,
          u.currentSize
        );
      }

      else if (u.status == UPLOAD_FILE_END) {
        Update.end(true);
      }
    }
  );

  server.begin();
}

void setup() {
  Serial.begin(115200);

  prefs.begin(
    "repeater",
    false
  );

  ssid =
    prefs.getString(
      "ssid",
      ""
    );

  pass =
    prefs.getString(
      "pass",
      ""
    );

  WiFi.mode(WIFI_AP_STA);

  WiFi.softAP(
    AP_SSID,
    AP_PASS
  );

  Serial.print("AP IP: ");
  Serial.println(
    WiFi.softAPIP()
  );

  connectWiFi();

  if (
    WiFi.status() ==
    WL_CONNECTED
  ) {
    enableNAT();
  }

  setupWeb();
}

void loop() {
  server.handleClient();

  static unsigned long last = 0;

  if (
    millis() - last >
    10000
  ) {
    last = millis();

    if (
      WiFi.status() != WL_CONNECTED &&
      ssid.length()
    ) {
      WiFi.disconnect();

      connectWiFi();

      if (
        WiFi.status() ==
        WL_CONNECTED
      ) {
        enableNAT();
      }
    }
  }
}
